public static String underlineToCamel(String string) {
    if (string == null || string.isEmpty()) {
        return "";
    }
    StringBuilder sb = new StringBuilder(string.length());
    boolean capitalizeNext = false;

    for (int i = 0; i < string.length(); i++) {
        char c = string.charAt(i);

        if (c == '_') {
            // Only set capitalizeNext if there's a next character and it's not an underscore
            if (i + 1 < string.length() && string.charAt(i + 1) != '_') {
                capitalizeNext = true;
            }
        } else {
            if (i == 0 && Character.isUpperCase(c)) {
                // Convert first character to lowercase if it's uppercase
                sb.append(Character.toLowerCase(c));
            } else if (capitalizeNext) {
                sb.append(Character.toUpperCase(c));
                capitalizeNext = false;
            } else {
                sb.append(c);
            }
        }
    }
    return sb.toString();
}

