public @NonNull ScoreAnalysis<Score_> diff(@NonNull ScoreAnalysis<Score_> other) {
    Objects.requireNonNull(other, "other");

    // Compute the score difference
    Score_ scoreDiff = score.subtract(other.score);

    // Collect all constraint refs from both analyses
    var allConstraintRefs = Stream.concat(
            constraintMap.keySet().stream(),
            other.constraintMap.keySet().stream()
    ).collect(Collectors.toSet());

    // Build the diff constraint map
    Map<ConstraintRef, ConstraintAnalysis<Score_>> diffConstraintMap = new HashMap<>();

    for (ConstraintRef constraintRef : allConstraintRefs) {
        ConstraintAnalysis<Score_> thisAnalysis = constraintMap.get(constraintRef);
        ConstraintAnalysis<Score_> otherAnalysis = other.constraintMap.get(constraintRef);

        ConstraintAnalysis<Score_> constraintDiff;
        if (thisAnalysis != null && otherAnalysis != null) {
            // Both present - check match data compatibility
            boolean thisHasMatches = thisAnalysis.matches() != null && !thisAnalysis.matches().isEmpty();
            boolean otherHasMatches = otherAnalysis.matches() != null && !otherAnalysis.matches().isEmpty();

            if (thisHasMatches != otherHasMatches) {
                throw new IllegalArgumentException(
                    "Cannot diff ScoreAnalysis objects with incompatible match data for constraint: " + constraintRef);
            }

            // Compute diff
            constraintDiff = thisAnalysis.diff(otherAnalysis);
        } else if (thisAnalysis != null) {
            // Only in this - use as-is
            constraintDiff = thisAnalysis;
        } else {
            // Only in other - negate it
            constraintDiff = otherAnalysis.negate();
        }

        // Check if the constraint diff should be included
        boolean hasNonZeroWeight = constraintDiff.weight() != null && !constraintDiff.weight().isZero();
        boolean hasNonZeroScore = constraintDiff.score() != null && !constraintDiff.score().isZero();
        boolean hasMatchDiffs = constraintDiff.matches() != null && !constraintDiff.matches().isEmpty();

        // Include only if there's any meaningful difference
        if (hasNonZeroWeight || hasNonZeroScore || hasMatchDiffs) {
            diffConstraintMap.put(constraintRef, constraintDiff);
        }
    }

    // Return new ScoreAnalysis with the diff, preserving this.isSolutionInitialized
    return new ScoreAnalysis<>(scoreDiff, diffConstraintMap, this.isSolutionInitialized);
}
